function largestVariance(s) {
  const codes = Array.from(s, ch => ch.charCodeAt(0) - 97);
  const total = new Array(26).fill(0);
  for (const code of codes) total[code]++;
  let best = 0;

  for (let major = 0; major < 26; major++) {
    for (let minor = 0; minor < 26; minor++) {
      if (major === minor || total[major] === 0 || total[minor] === 0) continue;
      let majorCount = 0;
      let minorCount = 0;
      let minorLeft = total[minor];
      for (const code of codes) {
        if (code === major) majorCount++;
        if (code === minor) {
          minorCount++;
          minorLeft--;
        }
        if (minorCount > 0) {
          best = Math.max(best, majorCount - minorCount);
        }
        if (majorCount < minorCount && minorLeft > 0) {
          majorCount = 0;
          minorCount = 0;
        }
      }
    }
  }

  return best;
}

