function largestVariance(s) {
  // Every substring: keep letter counts while extending the end, and take most frequent minus least frequent present letter.
  let best = 0;
  for (let start = 0; start < s.length; start++) {
    const count = new Array(26).fill(0);
    for (let end = start; end < s.length; end++) {
      count[s.charCodeAt(end) - 97]++;
      const present = count.filter(c => c > 0);
      best = Math.max(best, Math.max(...present) - Math.min(...present));
    }
  }
  return best;
}

