function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    const n = 10000;
    const mode = pick(3);
    if (mode === 0) return [Array.from({ length: n }, () => letters[pick(26)]).join('')];
    if (mode === 1) return [Array.from({ length: n }, () => rand() < 0.7 ? 'q' : 'z').join('')];
    // Mostly one letter, with a few scattered others.
    return [Array.from({ length: n }, () => rand() < 0.97 ? 'm' : letters[pick(26)]).join('')];
  }
  const alphabet = letters.slice(0, 1 + pick(4));
  const n = 1 + pick(12);
  const weight = rand();
  return [Array.from({ length: n }, () => rand() < weight ? alphabet[0] : alphabet[pick(alphabet.length)]).join('')];
}
